<?php $this->layout('default'); use Moves\Services\CmsAdmins as A; use Moves\Support\CmsView as V; $roles = []; foreach (A::roles() as $r) { $roles[$r['id']] = $r['name']; } $rows = A::listing(); ?>
<div class="cms-form-list"><form class="cms-card" method="post" action="/acao/admin-grant"><header class="cms-card-head"><div><h2>Conceder acesso</h2><small>A pessoa entra com a mesma conta do Realizze.</small></div><?= V::icon('shield') ?></header><?= V::csrf() ?><?= V::field('E-mail', 'email', '', ['type' => 'email', 'required' => true]) ?><?= V::field('Papel', 'role_id', '', ['type' => 'select', 'choices' => $roles]) ?><div class="cms-form-end"><button class="cms-btn-primary">Conceder acesso</button></div></form>
<section class="cms-card"><header class="cms-card-head"><div><h2>Administradores</h2></div><b class="cms-count"><?= count($rows) ?></b></header><?php foreach ($rows as $a): ?><form class="cms-row" method="post" action="/acao/admin-update"><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $a['id'] ?>"><div class="cms-cell"><i class="cms-avatar"><?= V::e(mb_strtoupper(mb_substr($a['first_name'], 0, 1) . mb_substr($a['last_name'], 0, 1))) ?></i><div><strong><?= V::e(trim($a['first_name'] . ' ' . $a['last_name'])) ?></strong><br><small><?= V::e($a['email']) ?></small></div></div><div class="cms-td-actions"><select name="role_id" aria-label="Papel"><?php foreach ($roles as $rid => $rname): ?><option value="<?= (int) $rid ?>"<?= (int) $rid === (int) $a['role_id'] ? ' selected' : '' ?>><?= V::e($rname) ?></option><?php endforeach; ?></select><select name="status" aria-label="Situação"><option value="active"<?= $a['status'] === 'active' ? ' selected' : '' ?>>Ativo</option><option value="inactive"<?= $a['status'] === 'inactive' ? ' selected' : '' ?>>Inativo</option></select><button class="cms-btn">Salvar</button></div></form><?php endforeach; ?></section></div>
